{"operation":"write","path":"search_glamorgan_2014.py","content":"import urllib.request
import re
from html.parser import HTMLParser

class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            for name, value in attrs:
                if name == 'href':
                    self.links.append(value)

# Fetch Wikipedia page for Glamorgan County Cricket Club
url = "https://en.wikipedia.org/wiki/Glamorgan_County_Cricket_Club"
req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'})
try:
    with urllib.request.urlopen(req) as response:
        html = response.read().decode('utf-8')

    # Find all links containing "2014" and "Glamorgan"
    links = re.findall(r'href="([^"]*Glamorgan[^"]*2014[^"]*)"', html)
    links += re.findall(r'href="([^"]*2014[^"]*Glamorgan[^"]*)"', html)

    print("Related links:")
    for link in links[:10]:
        print(link)

    # Search for "captain" mentions in the page
    # Look for the 2014 section
    if "2014" in html:
        # Find the section about 2014
        idx = html.find("2014")
        section = html[idx:idx+5000] if idx != -1 else ""
        # Find captain mentions
        captain_mentions = re.findall(r'.{0,300}captain.{0,300}', section, re.IGNORECASE)
        print("\nCaptain mentions:")
        for m in captain_mentions:
            print(m.replace('\n', ' ')[:200])
            print("---")

except Exception as e:
    print(f"Error: {e}")
"}

