// Save the result to a file using the File System API
async function save_result(data, filename) {
    try {
        const response = await fetch('data:text/plain;charset=utf-8,' + encodeURIComponent(data));
        const blob = await response.blob();
        const fs = require('fs');
        fs.writeFileSync(filename, data);
    } catch(e) {
        console.error('Error:', e);
    }
}

