                exsentences: 100,
                format: 'json'
            }
        });

        let extract = resp.data.query.pages[Object.keys(resp.data.query.pages)[0]].extract;
        console.log('Extract:', extract);

        // Save to file
        await save_result(extract, '/workspace/glamorgan_extract.txt');

    } catch(e) {
        console.error('Error:', e.message);
    }
}
search();
</script>
</body>
