{"operation":"run_python","code":"import urllib.request
import json
import re

def get_max_players(title):
    url = f"https://en.wikipedia.org/w/api.php?action=parse&page={title}&prop=text&format=json"
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    try:
        response = urllib.request.urlopen(req)
        data_text = json.loads(response.read().decode())
        text = data_text['parse']['text']['*']

        # Look for "Maximum players" or "Players" in the infobox
        match = re.search(r'Maximum players\s*:\s*(\d+)', text)
        if match:
            return int(match.group(1))
        match = re.search(r'Players\s*:\s*(\d+)\s*-', text)
        if match:
            return int(match.group(1))
        match = re.search(r'Players\s*:\s*(\d+)\s*players', text)
        if match:
            return int(match.group(1))
        return "Not found"
    except Exception as e:
        return str(e)

print("Zombies!!!:", get_max_players("Zombies!!!"))
print("Carcassonne:", get_max_players("Carcassonne"))"}

